# Each (idiomatic)
[1,2,3].each { |x| puts x }
5.times { |i| puts i }
(1..10).each { |i| }
1.upto(10) { |i| }
10.downto(1) { |i| }

# Methods (all methods return value of last expression)
def add(a, b)
  a + b             # implicit return
end

def add(a, b) = a + b   # one-liner (Ruby 3.0+)

# Explicit block parameter
def transform(arr, &block)
  arr.map(&block)
end
transform([1,2,3]) { |x| x * 2 }

# Proc and Lambda
add = Proc.new { |x, y| x + y }
add = proc { |x, y| x + y }
add = lambda { |x, y| x + y }
add = ->(x, y) { x + y }   # stabby lambda
